insert into public.sample_authors(id,handle,display_name,bio) values
('62c5b85f-d1f8-5f5e-a2de-7eab77823176','nemuri_lab','ねむり計測室','眠気と暮らしを観察する公式サンプル。実在の利用者ではありません。'),
('7ced12c9-135d-56cc-a169-9539ee33a5e4','kitchen_notes','台所の観察者','食べものと小さな失敗を記録する公式サンプル。実在の利用者ではありません。'),
('db53266a-6d71-5232-b35a-0be225fa9f57','train_window','通勤の窓際','移動時間の違和感を拾う公式サンプル。実在の利用者ではありません。'),
('0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','reply_pending','返信保留中','会話の温度差を考える公式サンプル。実在の利用者ではありません。'),
('4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','math_in_pocket','ポケットの数学','数式より先に生活で考える公式サンプル。実在の利用者ではありません。'),
('b17da883-163f-500d-b13b-5f5637787e9f','town_margin','まちの余白','身近な場所から社会を考える公式サンプル。実在の利用者ではありません。'),
('53380863-84ea-56fa-822b-97a117ce48ef','otaku_shelf','オタクの棚','好きな作品と部屋の関係を観察する公式サンプル。実在の利用者ではありません。'),
('7c500ff1-2e74-5d9b-adb2-bece30919a47','word_collector','言葉の採集者','日常語の裏側を眺める公式サンプル。実在の利用者ではありません。'),
('85768e26-eb90-58e2-a832-eac67f594703','object_philosophy','ものの哲学','物から暮らしを考える公式サンプル。実在の利用者ではありません。'),
('95e7c850-fe1e-5942-9f47-4c59bf813cb0','rainy_statistics','雨の日統計','天気をきっかけに考える公式サンプル。実在の利用者ではありません。') on conflict(id) do nothing;
insert into public.papers(id,sample_author_id,author,category,title,blocks,tags,created_at) values
('bea56ed5-a763-5139-a78f-d8e4c8cb99ae','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','二度寝にはなぜ第一回がないのか','[{"type":"text","heading":"問いと仮説","body":"目覚ましを止めた時点で、睡眠はもう一度始まっている。つまり『二度寝』は起きる決断を一度だけ保留した状態では。"},{"type":"text","heading":"検証計画（未実施）","body":"目覚ましを止めた時刻、布団を出た時刻、本人が「起きた」と宣言した時刻を別々に記録する。起床を一つの瞬間とみなす前提を疑う。"},{"type":"text","heading":"考察と反例","body":"二度寝の「一度目」は最初の睡眠ではなく、最初の起床決議だった可能性が高い。議事録のない決議は撤回しやすい。"}]'::jsonb,ARRAY['朝','睡眠']::text[],now() - interval '297 hours'),
('25ded25c-76e7-5a3c-b825-7b25dd628778','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','冷蔵庫の前で目的を忘れる','[{"type":"text","heading":"問いと仮説","body":"扉を開けた瞬間、何を取りに来たか分からなくなる。冷蔵庫には記憶を冷却する機能まで付いているのだろうか。"},{"type":"text","heading":"検証計画（未実施）","body":"冷蔵庫に向かう前に目的を声に出す日と、黙って開ける日を比べる。扉を開けてから三秒で思い出せるか記録する。"},{"type":"text","heading":"考察と反例","body":"冷気による記憶喪失説が正しければ声に出しても忘れるはず。思い出せるなら犯人は冷蔵庫ではなく、移動中に割り込んだ別の考えだ。"}]'::jsonb,ARRAY['冷蔵庫','日常']::text[],now() - interval '294 hours'),
('b1abca90-d9be-5f23-8596-f0c4c51407e5','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','電車の空席は近づくと消える','[{"type":"text","heading":"問いと仮説","body":"遠くから見えた席に向かう間に誰かが座る。席の存在は確定していたのに、所有権だけが未確定だった。"},{"type":"text","heading":"検証計画（未実施）","body":"見つけた空席までの距離と、そこへ着く前に座られた回数を記録する。混雑の程度もそろえる。"},{"type":"text","heading":"考察と反例","body":"『空席を発見した』と『座れる』の間には徒歩数秒の競争がある。遠くの空席は、存在していてもまだ自分の資源ではない。"}]'::jsonb,ARRAY['電車','通勤']::text[],now() - interval '291 hours'),
('98366b61-6c6d-5ea0-ab15-fda78a1e79ae','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','『いつでも返信して』が難しい理由','[{"type":"text","heading":"問いと仮説","body":"いつでもいいと言われると、いつが一番いいか考えてしまう。自由は気楽さだけでなく、タイミングを自分で決める負担も運んでくる。"},{"type":"text","heading":"検証計画（未実施）","body":"『いつでも』と言われたときの返信までの時間と、期限を指定されたときの時間を比べる。内容の重さもそろえる。"},{"type":"text","heading":"考察と反例","body":"自由な締切は、ときに締切を自分で作る仕事を増やす。相手の優しさを疑う研究ではなく、曖昧さの費用を数える研究である。"},{"type":"image","asset":"images/reply-at-night.jpg","caption":"この投稿のために生成した挿絵"}]'::jsonb,ARRAY['返信','会話']::text[],now() - interval '288 hours'),
('e9c9cf26-dd71-545c-8fe3-e25a8209f3dd','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','傘を持つ確率より濡れる後悔','[{"type":"text","heading":"問いと仮説","body":"降水確率を見て迷うが、選ぶ基準は確率だけではない。持ち歩く面倒さと、濡れたときの損失を別々に見積もると判断が変わる。"},{"type":"text","heading":"検証計画（未実施）","body":"雨の確率をp、傘を運ぶ面倒をC、濡れた損失をLとする。ざっくり p×L と C を比べ、予定別に値を変える。"},{"type":"text","heading":"考察と反例","body":"同じ降水確率でも、近所へ行く日と大事な紙を運ぶ日では答えが違う。確率そのものに正解を求めるのは、損失を忘れた計算である。"},{"type":"image","asset":"images/umbrella-choices.jpg","caption":"この投稿のために生成した挿絵"}]'::jsonb,ARRAY['確率','雨']::text[],now() - interval '285 hours'),
('6481d905-fc22-5009-8ad4-2668b3019eec','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','ベンチのない街は急ぐ人向けか','[{"type":"text","heading":"問いと仮説","body":"駅から家まで座れる場所が少ないと、移動しながら休むしかない。公共空間の設計は、歩き続けられる体を標準にしていないだろうか。"},{"type":"text","heading":"検証計画（未実施）","body":"ベンチのある通りとない通りで、誰が立ち止まれるかを観察する。距離だけでなく、座る場所の見つけやすさも見る。"},{"type":"text","heading":"考察と反例","body":"座らない人には無関係に見える椅子も、休みながら歩く人には道の一部だ。設置場所と維持管理を外した『増やせばよい』論にはしない。"}]'::jsonb,ARRAY['街','社会']::text[],now() - interval '282 hours'),
('dbe5ac1d-3824-5355-bc25-8b16b7604707','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','積んだ本は未読ではなく未来の選択肢','[{"type":"text","heading":"問いと仮説","body":"読んでいない本が増えると少し後ろめたい。でも棚にあるから、次の休日に手を伸ばせる。未読は可能性の在庫かもしれない。"},{"type":"text","heading":"検証計画（未実施）","body":"買った本を読む予定と、まだ読まない理由を分けて書く。本棚を眺めたときの満足も記録する。"},{"type":"text","heading":"考察と反例","body":"積読を全部失敗と数えれば、本棚は不良在庫になる。でも未来の自分が選べる幅には価値がある。床が埋まったら限界も見える。"}]'::jsonb,ARRAY['本','オタク']::text[],now() - interval '279 hours'),
('aaa9ba86-4e75-51a4-925e-92d1f033cc2e','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','『ちょっと』は長さを測らない','[{"type":"text","heading":"問いと仮説","body":"『ちょっと待って』のちょっとは、時計の単位ではなく相手を待たせる気まずさを薄める言葉だと思う。"},{"type":"text","heading":"検証計画（未実施）","body":"『ちょっと待って』を言った場面で、実際の待ち時間を測る。言った側と聞いた側の予想も聞く。"},{"type":"text","heading":"考察と反例","body":"『ちょっと』は秒針ではなく、相手への負担を軽く見せる包装紙だ。中身が十分を超えると、包装紙の効力は弱くなる。"}]'::jsonb,ARRAY['言葉','時間']::text[],now() - interval '276 hours'),
('f4de6a4e-6f85-59bc-8461-d103ee4dbfa5','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','片方の靴下はどこへ行くのか','[{"type":"text","heading":"問いと仮説","body":"洗濯機を疑って探したが、発見場所はベッドの下。事件の規模は小さいのに、失踪という物語を与えた瞬間、捜査が楽しくなった。"},{"type":"text","heading":"検証計画（未実施）","body":"洗濯機から取り出した直後、畳む直前、収納後に左右の枚数を記録する。捜索範囲は洗濯かごと袖まで広げる。"},{"type":"text","heading":"考察と反例","body":"『消えた』と名付ける前に、いつ見失ったかを特定する。犯人が靴下なら大事件だが、ベッドの下なら研究者の観測ミスである。"},{"type":"image","asset":"images/sock-detective.jpg","caption":"この投稿のために生成した挿絵"}]'::jsonb,ARRAY['洗濯','靴下']::text[],now() - interval '273 hours'),
('b8a9adbe-b68c-55f6-8d79-08ceccf18c2a','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','雨音は作業用の背景になる','[{"type":"text","heading":"問いと仮説","body":"窓の外の雨は聞こえるのに、隣の部屋の話し声ほど気にならない。意味のある音だけ脳が追いかけてしまうのか。"},{"type":"text","heading":"検証計画（未実施）","body":"同じ作業を雨音が聞こえる日と聞こえない日に行い、集中できたと感じた時間を記録する。作業の難しさもそろえる。"},{"type":"text","heading":"考察と反例","body":"雨音が助けになる人も、会話を聞き取りたい人には邪魔かもしれない。『集中音』という名前は、音より仕事の種類に依存する。"}]'::jsonb,ARRAY['雨','集中']::text[],now() - interval '270 hours'),
('524be286-2c33-5857-938b-20ec0e463d3f','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','枕の冷たい面は有限資源である','[{"type":"text","heading":"問いと仮説","body":"裏返した直後の幸福は大きい。でも三回目には裏も表も記憶を持ちはじめる。冷たさの供給には回復時間が必要だ。"},{"type":"text","heading":"検証計画（未実施）","body":"枕を返すたびに冷たさが戻るまでの時間を比べる。頬を当てた側と放置した側を同じ条件で触る。"},{"type":"text","heading":"考察と反例","body":"裏返しが効かなくなったら資源が枯れたのではなく、両面が温まっただけ。冷たい面を増やすには枕を増やすという、予算に厳しい結論になる。"}]'::jsonb,ARRAY['睡眠','観察']::text[],now() - interval '267 hours'),
('6c38eb5e-71a8-50dc-b22a-34fedc98f23a','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','残り一口だけ妙に大事','[{"type":"text","heading":"問いと仮説","body":"食べ始めは勢いで食べるのに、最後の一口は配分を考える。少ないほど価値を強く感じる、食卓の小さな希少性。"},{"type":"text","heading":"検証計画（未実施）","body":"同じ料理の最初と最後の一口を、何を見て選ぶかメモする。おいしさだけでなく『終わってしまう』感覚も聞く。"},{"type":"text","heading":"考察と反例","body":"最後が大事なのは味が凝縮するからとは限らない。食事の終了を自分で決める小さな儀式なら、残り一口は食べ物より句点に近い。"}]'::jsonb,ARRAY['食事','心理']::text[],now() - interval '264 hours'),
('6aed5b84-9140-59d1-97fd-6db6601827bd','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','いつもの道が工事中だと一日が新しい','[{"type":"text","heading":"問いと仮説","body":"一本裏道に入っただけで知らない店が三つ見えた。毎日の移動は、景色を省略する技術でもある。"},{"type":"text","heading":"検証計画（未実施）","body":"いつもの道と迂回路で、記憶に残った店や看板の数を比べる。歩行時間の差も記録する。"},{"type":"text","heading":"考察と反例","body":"新しい道が面白いのは街が変わったからではなく、頭の自動運転が切れたからかもしれない。工事を歓迎する結論は通勤時間を考えると保留したい。"}]'::jsonb,ARRAY['街','散歩']::text[],now() - interval '261 hours'),
('ccf4e10f-7272-54d4-96ed-50d79083e03d','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','既読より『書きかけ』が重い','[{"type":"text","heading":"問いと仮説","body":"返事を考えて入力欄まで開いたのに、言葉が決まらない。相手には何も見えない時間に、こちらだけ長い会議をしている。"},{"type":"text","heading":"検証計画（未実施）","body":"書きかけの時間と、実際に送った文字数を比べる。送らなかった文は公開せず、自分のメモだけに残す。"},{"type":"text","heading":"考察と反例","body":"相手が見えるのは短い返事でも、こちらの頭では編集会議が長引く。送信前の労働は既読表示に載らない。"}]'::jsonb,ARRAY['返信','日常']::text[],now() - interval '258 hours'),
('b7e94701-db40-5f6d-9d8d-6d442cd03fe1','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','食べもの','レシートの合計は最後だけ驚く','[{"type":"text","heading":"問いと仮説","body":"一品ずつは小さい金額でも、合計になると大きい。加算は簡単なのに、買い物中の頭は平均値で予算を見ている気がする。"},{"type":"text","heading":"検証計画（未実施）","body":"買い物中に一品ごとの価格を足した予想額と、レジの合計を比べる。税や値引きは別に記録する。"},{"type":"text","heading":"考察と反例","body":"『一つ百円台』を十回繰り返すと千円台になる。驚きの原因が計算能力か注意の配分かを分けないと、財布を冤罪にする。"}]'::jsonb,ARRAY['買い物','数']::text[],now() - interval '255 hours'),
('7638bf0e-44d6-5ba6-b97b-b8b2f7283036','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','『無料』の作業は誰かの時間でできている','[{"type":"text","heading":"問いと仮説","body":"町内の案内や地域イベントは、好意だけで回っているように見える。継続を考えるなら、見えない準備時間まで数えたい。"},{"type":"text","heading":"検証計画（未実施）","body":"無料で使うサービスの裏に、誰の時間と設備が必要か書き出す。料金がないことと費用がないことを分ける。"},{"type":"text","heading":"考察と反例","body":"無料の恩恵は本物だが、費用が消えるわけではない。支払う人が見えなくなるほど、便利さの説明は不完全になる。"}]'::jsonb,ARRAY['地域','労働']::text[],now() - interval '252 hours'),
('30f26814-1a12-5d15-bf0c-0e76f10fe1f7','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','アニメの最終回後に部屋が静か','[{"type":"text","heading":"問いと仮説","body":"毎週の予定が一つ消えると、時計より先に生活のリズムが変わる。作品への愛着には曜日も含まれていたのだ。"},{"type":"text","heading":"検証計画（未実施）","body":"毎週その作品を見ていた時刻に、最終回後の一週間で何をしたか記録する。喪失感と単なる時間の空白を分ける。"},{"type":"text","heading":"考察と反例","body":"物語が終わると登場人物だけでなく、一週間の予定表にいた『放送時間』も消える。二期を望む気持ちは、部屋の静けさへの抗議でもある。"}]'::jsonb,ARRAY['アニメ','文化']::text[],now() - interval '249 hours'),
('26bf6081-23ca-52fb-9170-268a62cc1a94','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','暮らし','雨上がりの『もう晴れた』','[{"type":"text","heading":"問いと仮説","body":"雲が残っていても、傘を閉じられるなら晴れたと言う。天気の言葉は空だけでなく、自分の行動で決まる。"},{"type":"text","heading":"検証計画（未実施）","body":"雨が止んでから『晴れた』と言うまでの空の状態を記録する。雲の量と気分も分ける。"},{"type":"text","heading":"考察と反例","body":"晴れの定義は気象台だけが持つわけではない。傘を閉じられた人の『晴れた』は、雲より行動の自由を報告している。"}]'::jsonb,ARRAY['雨','言葉']::text[],now() - interval '246 hours'),
('deffd176-6868-5e25-9de9-73bda9a1008f','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','空の箱を捨てにくい','[{"type":"text","heading":"問いと仮説","body":"中身があった時の役割を、箱がまだ覚えているように見える。実際には私が『いつか使う』という未来をしまっている。"},{"type":"text","heading":"検証計画（未実施）","body":"空き箱を残した理由を、修理・再利用・なんとなくに分ける。一か月後も使ったか確認する。"},{"type":"text","heading":"考察と反例","body":"箱の価値は中身が消えたあとも『いつか使う』という未来形で残る。保管料を家賃換算すると、空き箱は意外に高級な住人だ。"}]'::jsonb,ARRAY['片付け','哲学']::text[],now() - interval '243 hours'),
('0c4f66bd-c66c-5c1f-a3ad-2376ef9444d3','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','天気予報を見たあと窓も見る','[{"type":"text","heading":"問いと仮説","body":"画面の予報が正確でも、自分の家の前を確かめたい。広い地域の情報と、玄関を出る判断の間には最後の確認がある。"},{"type":"text","heading":"検証計画（未実施）","body":"予報を見て窓も見るとき、何を確かめたいのか一行で書く。外出予定がない日も比べる。"},{"type":"text","heading":"考察と反例","body":"予報は未来の確率、窓は今の現場だ。両方を見るのは情報の重複ではなく、統計と実況を突き合わせる小さな査読かもしれない。"}]'::jsonb,ARRAY['天気','判断']::text[],now() - interval '240 hours'),
('15b5ee8e-3a85-54e1-82e1-80c9d22a0f82','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','寝る前の一分は伸縮する','[{"type":"text","heading":"問いと仮説","body":"歯磨き前の一分は短いのに、動画を『一本だけ』見る一分は三十分に育つ。時計より先に行動を定義した方がよさそう。"},{"type":"text","heading":"検証計画（未実施）","body":"「一本だけ」と決めた動画の実際の長さと、歯磨きを先にした日の就寝時刻を比べる。"},{"type":"text","heading":"考察と反例","body":"分という単位は伸びない。伸びるのは次の動画に移るまでの意思決定だ。時計ではなく再生ボタンを研究対象にすべきである。"}]'::jsonb,ARRAY['夜','時間']::text[],now() - interval '237 hours'),
('91570fae-658d-5953-9173-7faae78996f4','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','カレーは翌日の方が会話が上手い','[{"type":"text","heading":"問いと仮説","body":"初日は具材が別々に自己紹介している。翌日は同じ話題でまとまっている。味の変化を人間関係にたとえると少し分かる。"},{"type":"text","heading":"検証計画（未実施）","body":"作った直後と翌日のカレーを同じ温度で比べる。空腹度と付け合わせをそろえないと『二日目の勝利』は判定できない。"},{"type":"text","heading":"考察と反例","body":"味が丸くなるという比喩は楽しいが、記憶も調味料になる。翌日に期待して食べる自分が、味を少し先回りしている可能性は残る。"}]'::jsonb,ARRAY['カレー','比喩']::text[],now() - interval '234 hours'),
('fe2b7458-df7e-5401-892b-b82ad9ec6c6c','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','信号待ちの二分は長い','[{"type":"text","heading":"問いと仮説","body":"家での二分は一瞬なのに、横断歩道では長い。目的地が見えている時間は、待つことを余計に意識させる。"},{"type":"text","heading":"検証計画（未実施）","body":"信号と家で同じ二分を過ごし、時計を見た回数を数える。スマホを触る条件も分ける。"},{"type":"text","heading":"考察と反例","body":"赤信号が時間を伸ばすわけではない。向こう岸が見えているのに渡れない状態が、残り秒数を主役にしている。"}]'::jsonb,ARRAY['時間','街']::text[],now() - interval '231 hours'),
('e90875ed-7bdc-53ce-b644-7b9de500b5a0','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','雑談の『それで？』は小さな招待状','[{"type":"text","heading":"問いと仮説","body":"内容を増やせという命令にも聞こえるが、続きを聞きたいという合図でもある。短い相づちの意味は関係性で変わる。"},{"type":"text","heading":"検証計画（未実施）","body":"『それで？』が嬉しかった場面と急かされた場面を一つずつ思い出し、声の調子と関係性を比べる。"},{"type":"text","heading":"考察と反例","body":"同じ二文字でも、好奇心と圧迫の境目は文面の外にある。文字だけで判定する研究には、会話の前後が欠けている。"}]'::jsonb,ARRAY['会話','言葉']::text[],now() - interval '228 hours'),
('e02cae65-0721-5340-a546-8a5938dbd671','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','五分の遅刻と五分の余裕は非対称','[{"type":"text","heading":"問いと仮説","body":"同じ五分でも、遅刻には謝罪が付いて、余裕には何も付かない。時間の価値はゼロを境に急に曲がる。"},{"type":"text","heading":"検証計画（未実施）","body":"集合時刻の前後五分に対する気分を数値化してみる。相手が待つ場合と自分だけの場合を分ける。"},{"type":"text","heading":"考察と反例","body":"時間の価値は直線ではない。締切という境界を一歩越えると、同じ五分に謝罪という別料金が発生する。"}]'::jsonb,ARRAY['時間','数学']::text[],now() - interval '225 hours'),
('c9f4aaa2-8faf-54c2-99e6-1414848e448d','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','駅前の木陰は小さなインフラ','[{"type":"text","heading":"問いと仮説","body":"日差しの強い日に、木が一本ある場所だけ人の歩く速度が変わる。道路の幅だけでなく、立ち止まれる快適さも公共性だと思う。"},{"type":"text","heading":"検証計画（未実施）","body":"日なたと木陰で立ち止まる人数を同じ時刻に観察する。季節、雨、風の条件をそろえる。"},{"type":"text","heading":"考察と反例","body":"木陰を『景色』として扱うと、通行を助ける働きを見落とす。冬には日なたの方が選ばれる可能性もあり、木だけの勝利とは言えない。"}]'::jsonb,ARRAY['街','環境']::text[],now() - interval '222 hours'),
('d586cce8-2e04-5228-9f12-8600d311746a','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','推しの新情報で急に姿勢が良くなる','[{"type":"text","heading":"問いと仮説","body":"通知を見る前は床に寝転んでいたのに、開くと座り直している。情報の重さは身体の角度に出る。"},{"type":"text","heading":"検証計画（未実施）","body":"新情報を見た直後に何をしたか、スクリーンショットを撮ったか、誰に話したかをメモする。"},{"type":"text","heading":"考察と反例","body":"姿勢が良くなるという比喩を身体測定にしてはいけない。重要なのは一つの通知が、その後の数分の行動をどれだけ組み替えたかだ。"}]'::jsonb,ARRAY['推し','日常']::text[],now() - interval '219 hours'),
('4bded568-05b4-5144-8dee-ca6d482ccdeb','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','『普通は』と言う前に立ち止まる','[{"type":"text","heading":"問いと仮説","body":"普通という言葉は便利だが、誰の経験を集めた普通なのかが省略される。説明を一行増やす方が、話は遠回りせずに済むことがある。"},{"type":"text","heading":"検証計画（未実施）","body":"『普通は』を使いたくなった場面で、誰の経験を標準にしたか一行で書く。反例を一つ探す。"},{"type":"text","heading":"考察と反例","body":"多数派の説明には使えても、相手への命令に変わると議論が止まる。『私の周りでは』と言い換えるだけで、反例が座れる席ができる。"}]'::jsonb,ARRAY['言葉','社会']::text[],now() - interval '216 hours'),
('5ebf359c-d8cb-580a-9a63-88f30a822678','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','鍵を探すとき鍵はいつも見ている','[{"type":"text","heading":"問いと仮説","body":"最後に置いたのは自分のはず。持ち主の記憶より、物の現在位置の方が正確なのが少し悔しい。"},{"type":"text","heading":"検証計画（未実施）","body":"鍵を見つけた場所と、探している最中に何回そこを見たか記録する。急いでいない日も比べる。"},{"type":"text","heading":"考察と反例","body":"鍵が隠れたのではなく、探す『はずの場所』に注意が集まった可能性がある。鍵の擬人化は楽しいが、置き場所を固定する方が再現性は高い。"}]'::jsonb,ARRAY['鍵','日常']::text[],now() - interval '213 hours'),
('1c76e10e-db03-5de4-9b2a-42437d9847b8','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','傘を忘れた日に限って降る気がする','[{"type":"text","heading":"問いと仮説","body":"忘れた日だけ強く記憶に残り、持っていた日の小雨は数えていない。体感の確率を作る前に、忘れなかった日も記録してみたい。"},{"type":"text","heading":"検証計画（未実施）","body":"傘を持った日と忘れた日の降雨を同じ期間だけ記録する。印象に残った日だけを集めない。"},{"type":"text","heading":"考察と反例","body":"忘れた日に降る法則が本当なら傘屋は予報会社を買うはずだ。濡れた日の記憶が強いという説明にも、晴れて忘れた日の記録が必要である。"}]'::jsonb,ARRAY['雨','確率']::text[],now() - interval '210 hours'),
('6c9a7e62-c2b9-5768-9363-8671c1dbd49f','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','休日の朝、早く起きる謎','[{"type":"text","heading":"問いと仮説","body":"平日は布団から出られない。休日は予定がなくても目が覚める。睡眠の敵は時刻ではなく『出勤する』という文脈かもしれない。"},{"type":"text","heading":"検証計画（未実施）","body":"平日と休日の起床時刻だけでなく、起きた直後に待つ予定を記録する。翌日に楽しい予定がある平日も比較対象にする。"},{"type":"text","heading":"考察と反例","body":"休日の早起きを「体が元気」と解釈するのは早い。起床を妨げるのは睡眠不足だけでなく、起きた後に何が待つかという予測かもしれない。"}]'::jsonb,ARRAY['休日','睡眠']::text[],now() - interval '207 hours'),
('2512bbed-33f2-5359-9ce1-381f2c709eef','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','買い物メモに書いた物だけ忘れる','[{"type":"text","heading":"問いと仮説","body":"頭に浮かんだ時点で安心してしまい、店ではメモを見ることも忘れる。記録は記憶の代わりになるが、記録の存在を覚える仕組みが必要。"},{"type":"text","heading":"検証計画（未実施）","body":"店に着いたら買い物メモを先に開く日と、思い出してから開く日を比べる。忘れ物の数を数える。"},{"type":"text","heading":"考察と反例","body":"メモを作った達成感は、買った達成感ではない。研究上の最大の落とし穴は『メモを見る』という手順がメモに書かれていないことだ。"}]'::jsonb,ARRAY['買い物','習慣']::text[],now() - interval '204 hours'),
('33df6f16-edc9-5829-8912-e1d6c239ec97','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','改札前で歩幅がそろう','[{"type":"text","heading":"問いと仮説","body":"知らない人同士なのに、改札が近づくと自然に速度が似る。都市には音のない合図が多い。"},{"type":"text","heading":"検証計画（未実施）","body":"改札までの距離ごとに歩行速度を観察する。立ち止まる人やスーツケースを持つ人は別に扱う。"},{"type":"text","heading":"考察と反例","body":"群衆が一つの生き物のように見えるが、速度がそろう理由は改札の処理能力かもしれない。『暗黙の合図』説には改札前の幅も測る必要がある。"}]'::jsonb,ARRAY['駅','観察']::text[],now() - interval '201 hours'),
('5ddf310d-4824-574e-9750-4daa66e2d6ec','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','断る文面だけ丁寧になりすぎる','[{"type":"text","heading":"問いと仮説","body":"断りたいという一点を伝えるために、前置きが四行になる。相手を尊重する言葉と、責任をぼかす言葉は似ている。"},{"type":"text","heading":"検証計画（未実施）","body":"断るメッセージの前置きの長さと、結論が現れる位置を比べる。相手に内容が伝わったかも確かめる。"},{"type":"text","heading":"考察と反例","body":"丁寧な文ほど親切とは限らない。断る理由を四行書いて結論を隠すと、読み手に『結局どっち？』という追加作業を頼むことになる。"}]'::jsonb,ARRAY['断り方','言葉']::text[],now() - interval '198 hours'),
('5c143fcb-d660-590e-bcfe-1ae7a198ae3e','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','行列の長さは待ち時間を教えない','[{"type":"text","heading":"問いと仮説","body":"三人の列でも一人が大量購入なら長い。人数だけでなく、一人あたりの処理時間の分布を見る必要がある。短い列に毎回負ける理由が少し分かった。"},{"type":"text","heading":"検証計画（未実施）","body":"待ち時間を『前の人数×一人あたりの会計時間』として予測し、実測と比べる。大量購入や返品は別記する。"},{"type":"text","heading":"考察と反例","body":"人数が少なくても一人が長ければ負ける。予測を外した回だけ記憶する癖もありそうなので、勝った列も必ず記録する。"}]'::jsonb,ARRAY['行列','確率']::text[],now() - interval '195 hours'),
('44cd93c6-d2fe-52f9-a280-2cfa59569a22','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','便利なアプリの『前提』を数える','[{"type":"text","heading":"問いと仮説","body":"スマホ、通信、読める文字、使える手、静かな場所。手続きが簡単になったと言うとき、何を持っている人の話なのか確認したい。"},{"type":"text","heading":"検証計画（未実施）","body":"登録、支払い、通知設定までの手順を数え、スマホに慣れない人にも一緒に試してもらう。"},{"type":"text","heading":"考察と反例","body":"『誰でも簡単』の主語を確かめたい。最新端末と本人確認書類を持つ人だけが通れる入口なら、便利さには見えない入場条件がある。"}]'::jsonb,ARRAY['社会','デジタル']::text[],now() - interval '192 hours'),
('9e2e24d9-474a-5c3e-91a4-8989176fd037','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','グッズを飾る場所にも編集がある','[{"type":"text","heading":"問いと仮説","body":"全部見せると散らかる。厳選すると寂しい。棚は『好き』の総量ではなく、その日の見せ方を決める編集面だ。"},{"type":"text","heading":"検証計画（未実施）","body":"同じグッズを棚の中央と引き出しに置いた日で、目に入る回数と気分を比べる。"},{"type":"text","heading":"考察と反例","body":"飾るとは所有物の順位を編集する作業である。ただし見せない収納にも大切にする形があり、展示数を愛の量にしてはいけない。"}]'::jsonb,ARRAY['グッズ','部屋']::text[],now() - interval '189 hours'),
('68b2af64-e27e-53da-9ab0-24bf05feb4a6','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','暮らし','『あとで』は未来のどこか','[{"type":"text","heading":"問いと仮説","body":"場所を決めていない待ち合わせみたいな言葉。あとでと言うなら、せめて今日なのか今週なのかを付けたい。"},{"type":"text","heading":"検証計画（未実施）","body":"『あとでやる』と言った後、実際に行った時刻を記録する。期限を言った場合との違いを見る。"},{"type":"text","heading":"考察と反例","body":"『あとで』は予定ではなく、現在の仕事を遠ざける技術かもしれない。未来のどこにも予約していなければ、未来も引き受けてくれない。"}]'::jsonb,ARRAY['言葉','予定']::text[],now() - interval '186 hours'),
('3af2abff-c990-5ece-bba5-5dad109dbcea','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','ペンの残量とやる気は連動しない','[{"type":"text","heading":"問いと仮説","body":"書く気満々の日に限ってインクが出ない。意志だけでなく道具の状態も行動の一部だと気づく。"},{"type":"text","heading":"検証計画（未実施）","body":"インク残量を変えずに、書き始めるまでの時間を比べる。新しいペンを買った直後も観察する。"},{"type":"text","heading":"考察と反例","body":"新品がやる気を生むとしても、最初の一ページだけかもしれない。筆記具に期待しすぎる研究は、締切という強い交絡因子を忘れがちだ。"}]'::jsonb,ARRAY['文房具','道具']::text[],now() - interval '183 hours'),
('c301de6f-d160-51e0-a1ed-bacaa3aca5d9','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','濡れた靴の帰り道は遠い','[{"type":"text","heading":"問いと仮説","body":"距離は同じでも、一歩ごとに靴下を意識する。身体の不快さが、道の長さに混ざってくる。"},{"type":"text","heading":"検証計画（未実施）","body":"靴が濡れた日と乾いた日で、同じ帰路の体感時間を比べる。歩幅と寄り道も見る。"},{"type":"text","heading":"考察と反例","body":"道の長さが変わらなくても、一歩ごとに靴下のことを考えれば時間は長く感じる。足元の不快感は時計ではなく注意を占領する。"}]'::jsonb,ARRAY['雨','帰宅']::text[],now() - interval '180 hours'),
('53494b92-f5fd-56a0-b665-5487e18a75d3','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','布団は室温を交渉材料に使う','[{"type":"text","heading":"問いと仮説","body":"起床五分前だけ部屋が急に寒く感じる。温度計が変わらなくても、外に出る予定が体感温度を書き換えている。"},{"type":"text","heading":"検証計画（未実施）","body":"室温を測り、起床前後の「寒い」という主観評価を記録する。布団に戻れる日と戻れない日を分ける。"},{"type":"text","heading":"考察と反例","body":"温度計が同じなら布団の特殊能力ではない。『出ると損をする』という予感が寒さに加算されている。冬の朝の損失計算はたいてい布団が勝つ。"}]'::jsonb,ARRAY['朝','仮説']::text[],now() - interval '177 hours'),
('b2f43bc5-44f4-5e29-90b8-18865cac09ba','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','暮らし','皿洗いは始めるまでが長い','[{"type":"text","heading":"問いと仮説","body":"洗い始めれば数分で終わる。だが山を見ている時間は妙に長い。作業量より着手の摩擦を測った方が、家事の本質に近そう。"},{"type":"text","heading":"検証計画（未実施）","body":"皿の枚数と洗い始めるまでの時間を測り、洗い始めてからの所要時間と比べる。二枚だけ洗う日も作る。"},{"type":"text","heading":"考察と反例","body":"家事を敵として巨大化させていたのは、流しの山を眺める時間かもしれない。ただし水が冷たい日は着手の摩擦に物理的根拠がある。"}]'::jsonb,ARRAY['家事','台所']::text[],now() - interval '174 hours'),
('e9c98ce4-b69a-5dd9-a1f0-42c90c671f69','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','駅のアナウンスだけよく聞き逃す','[{"type":"text","heading":"問いと仮説","body":"必要な情報ほど雑音に埋もれる。『次は何番線』の直前に考え事を始める自分の脳も、共同犯だ。"},{"type":"text","heading":"検証計画（未実施）","body":"案内を聞き逃した瞬間にしていた作業を記録する。静かな駅と騒がしい駅を分けて考える。"},{"type":"text","heading":"考察と反例","body":"駅の音量を上げれば解決するとは限らない。『聞く準備ができていない人』の注意まで、スピーカーでは操作できないからだ。"}]'::jsonb,ARRAY['駅','注意']::text[],now() - interval '171 hours'),
('644271a5-7375-53b2-adcb-a61c896e2421','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','沈黙は会話の故障ではない','[{"type":"text","heading":"問いと仮説","body":"親しい人と歩いていると、話題がない時間も居心地がよい。会話を続ける能力より、止めておける信頼が働いている。"},{"type":"text","heading":"検証計画（未実施）","body":"親しい人と黙って歩いた時間を、気まずかったかどうか後で振り返る。初対面の場合とも比べる。"},{"type":"text","heading":"考察と反例","body":"沈黙に意味を与えすぎると、会話の休憩を故障扱いしてしまう。安心して黙れる関係は、話題の豊富さとは別の技能である。"}]'::jsonb,ARRAY['沈黙','友人']::text[],now() - interval '168 hours'),
('0d0bb051-da99-581f-bbad-f0ed0459775d','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','『あと一回』は停止規則ではない','[{"type":"text","heading":"問いと仮説","body":"動画もゲームも、次が気になる構造なら一回の終点は始点にもなる。続けるかどうかを毎回決めるより、先に終了時刻を決めたい。"},{"type":"text","heading":"検証計画（未実施）","body":"動画を一本ごとにやめる条件と、終了時刻を先に決める条件を比べる。翌日の眠気も費用として見る。"},{"type":"text","heading":"考察と反例","body":"『あと一回』は回数を減らす命令に見えるが、次の開始を許す命令でもある。境界を動画の外に置くと、この循環から抜けやすい。"}]'::jsonb,ARRAY['習慣','ゲーム']::text[],now() - interval '165 hours'),
('2b3b160d-3b75-5859-a398-269624c823c4','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','待合室の椅子は情報を持っている','[{"type":"text","heading":"問いと仮説","body":"椅子の数や並び方を見ると、そこに何人がどれくらい待つ想定か分かる。設計図に書かれない期待が家具に残る。"},{"type":"text","heading":"検証計画（未実施）","body":"待合室の椅子の数、並び方、背もたれの有無を記録する。立って待つ人がいる時間帯も見る。"},{"type":"text","heading":"考察と反例","body":"座席は家具であると同時に『どれほど待つ想定か』という施設からの返事だ。ただし椅子が多いほど待ち時間が長いとは限らない。"}]'::jsonb,ARRAY['公共空間','観察']::text[],now() - interval '162 hours'),
('f4e4aa2f-6499-5c3b-96ee-78fe2fc4cbbb','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','『一話だけ』は研究上の危険語','[{"type":"text","heading":"問いと仮説","body":"続きが気になる構成を知りながら再生する。一話という単位は、視聴時間の安全装置としては弱い。"},{"type":"text","heading":"検証計画（未実施）","body":"一話で止められた日と、次回予告まで見た日を比べる。翌日の時間も含めて考える。"},{"type":"text","heading":"考察と反例","body":"作品が面白いほど停止条件は壊れやすい。『一話だけ』は作品側に終点を委ねる言葉で、物語はだいたい次の一話を用意している。"}]'::jsonb,ARRAY['アニメ','夜']::text[],now() - interval '159 hours'),
('ad1e5e52-8a36-5ee2-8275-0acdb9b708c6','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','『お疲れさま』は万能すぎる','[{"type":"text","heading":"問いと仮説","body":"挨拶にも労いにも、会話の終わりにも使える。同じ音が一日に何度も違う役目で働いている。"},{"type":"text","heading":"検証計画（未実施）","body":"挨拶、ねぎらい、会話の終わりで使う『お疲れさま』を集める。返事の違いも見る。"},{"type":"text","heading":"考察と反例","body":"一語で多くを済ませる便利さがある一方、何をねぎらっているかは曖昧になる。万能な言葉ほど、具体的な一言を足せる余地がある。"}]'::jsonb,ARRAY['言葉','挨拶']::text[],now() - interval '156 hours'),
('91f4d678-3891-5aa2-bb52-bd91cd61fb67','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','お気に入りのコップは容量以上の働きをする','[{"type":"text","heading":"問いと仮説","body":"同じ水でも、そのコップだと休憩の気分になる。道具の価値を機能だけで測ると、習慣との結び付きを見落とす。"},{"type":"text","heading":"検証計画（未実施）","body":"同容量の別のコップで同じ飲み物を飲み、飲む量と気分を比べる。洗いやすさも評価する。"},{"type":"text","heading":"考察と反例","body":"お気に入りの働きは容量だけでは測れない。朝に手が伸びる確率を上げるなら、それは容器であり小さな習慣装置でもある。"}]'::jsonb,ARRAY['食器','哲学']::text[],now() - interval '153 hours'),
('0df210c5-48a3-5ee3-bd11-c00a7f965b69','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','洗濯予報より雲の顔色を見る','[{"type":"text","heading":"問いと仮説","body":"予報を確認したのに、空が暗いと干すのをためらう。数字と目の前の景色が違うとき、判断は意外と感情寄りになる。"},{"type":"text","heading":"検証計画（未実施）","body":"予報が晴れでも雲を見て洗濯を迷った日を記録する。実際に乾いたかも後で確かめる。"},{"type":"text","heading":"考察と反例","body":"雲は身近な証人だが、空の一部しか見ていない。予報も完全ではない。どちらを信じたかより、どちらがどんな失敗をしたか比べたい。"}]'::jsonb,ARRAY['洗濯','天気']::text[],now() - interval '150 hours'),
('594d1c7d-25a6-5ade-adc3-fa5e683d31f5','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','夢の中の駅は乗り換えが雑','[{"type":"text","heading":"問いと仮説","body":"改札の先が教室でも、夢の中では疑わない。世界の設定より『今は急いでいる』という感情が優先されるらしい。"},{"type":"text","heading":"検証計画（未実施）","body":"夢日記に駅の構造と自分が感じた急ぎ具合を分けて書く。翌朝、現実の路線図と照合する。"},{"type":"text","heading":"考察と反例","body":"夢の駅員に接続の説明を求めても無駄だろう。物理法則より『遅れそう』という物語の都合が優先される世界だからである。"}]'::jsonb,ARRAY['夢','日常']::text[],now() - interval '147 hours'),
('fc1cc2be-b7c5-57f8-b942-ffeb0b1f9db2','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','トーストの焼き加減に思想が出る','[{"type":"text","heading":"問いと仮説","body":"薄いきつね色で止める人と、縁の黒さまで待つ人がいる。同じパンでも『完成』の定義は意外と個人的だ。"},{"type":"text","heading":"検証計画（未実施）","body":"『こんがり』という言葉で他人が想像する色を見比べる。色見本を使い、食感の好みも一緒に聞く。"},{"type":"text","heading":"考察と反例","body":"焦げた縁を愛する人と避ける人では、成功の定義が違う。トースターは同じ熱を出しても、満足の温度は共有できない。"}]'::jsonb,ARRAY['朝食','好み']::text[],now() - interval '144 hours'),
('0a251d69-0c56-524a-8631-777cd36cc06d','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','エスカレーターの立ち位置に地元が出る','[{"type":"text","heading":"問いと仮説","body":"旅行先でいつもの側に立ったら流れが違った。身体が覚える規則は、標識より強いことがある。"},{"type":"text","heading":"検証計画（未実施）","body":"旅先で無意識に立った側と、現地で人が多く立つ側を記録する。看板の有無も確認する。"},{"type":"text","heading":"考察と反例","body":"習慣は自分の体に入ったローカル規則だ。ただし周囲の流れに合わせる人もいるので、地域差を全員の性格に還元してはいけない。"}]'::jsonb,ARRAY['旅行','習慣']::text[],now() - interval '141 hours'),
('1cf70a77-ce58-54b0-906f-2aa65a9e46d1','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','グループ会話の送信ボタンは重い','[{"type":"text","heading":"問いと仮説","body":"一対一なら軽い一文が、五人宛てになると説明文に変わる。読者が増えるほど、口調も公的になる。"},{"type":"text","heading":"検証計画（未実施）","body":"同じ一文を一対一とグループ宛てに書き、書き直した箇所を比べる。送信はしなくてもよい。"},{"type":"text","heading":"考察と反例","body":"読者が増えると、内輪の言葉は説明を要求される。グループチャットは小さな公開講演で、送信前に勝手に司会が生まれる。"}]'::jsonb,ARRAY['チャット','会話']::text[],now() - interval '138 hours'),
('a62b3276-bcc0-58d0-b3d5-42c3431cc434','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','人間関係','割り勘の端数に性格が集まる','[{"type":"text","heading":"問いと仮説","body":"数字としては数円でも、『誰が多く払うか』には公平感が乗る。均等と納得は同じ関数ではない。"},{"type":"text","heading":"検証計画（未実施）","body":"一円単位の均等さと、全員が納得したかを別々に聞く。立て替えた人の手間も数える。"},{"type":"text","heading":"考察と反例","body":"数学的に等しい支払いが、社会的に公平とは限らない。小銭三円を守るために全員を五分待たせたら、時間の割り勘が崩れる。"}]'::jsonb,ARRAY['割り勘','公平']::text[],now() - interval '135 hours'),
('26222e71-0946-568c-95cd-2731ba427a8b','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','段差一つを『小さい』と言える条件','[{"type":"text","heading":"問いと仮説","body":"段差の高さだけなら小さい。でも荷物、疲れ、移動手段が加わると、同じ高さが別の障壁になる。障害は物だけでなく環境との関係にある。"},{"type":"text","heading":"検証計画（未実施）","body":"同じ段差を、荷物を持たずに歩く場合とベビーカーや車輪付きバッグを使う場合で比べる。安全な範囲で行う。"},{"type":"text","heading":"考察と反例","body":"高さは同じでも障害の大きさは人によって変わる。『この程度』という判断は段差の測定値ではなく、自分の身体条件を含んだ意見だ。"}]'::jsonb,ARRAY['街','社会']::text[],now() - interval '132 hours'),
('1429f5ec-3e17-5ddd-9a96-0fa66d610e9b','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','同じ作品を見返すのは答え合わせ','[{"type":"text","heading":"問いと仮説","body":"結末を知ってから序盤を見ると、何気ない台詞の意味が変わる。作品は変わらないのに、観客の側に新しい文脈ができる。"},{"type":"text","heading":"検証計画（未実施）","body":"初見で好きだった場面と、見返して新しく気づいた場面を並べる。結末を知った影響も書く。"},{"type":"text","heading":"考察と反例","body":"二周目は同じ作品を見ているようで、観客の頭に新しい資料が入っている。答え合わせというより、研究対象を変えずに研究者が変わった実験だ。"}]'::jsonb,ARRAY['物語','考察']::text[],now() - interval '129 hours'),
('5cc53af3-ce44-5503-a1f9-c561209f604a','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','暮らし','『気が向いたら』の気はどこにいる','[{"type":"text","heading":"問いと仮説","body":"予定表には書けないが、ある日急に掃除を始める。気分を待つより、五分だけ始める方が呼び出しやすいかもしれない。"},{"type":"text","heading":"検証計画（未実施）","body":"掃除を始めた日の直前の行動を書き出す。『気が向くまで待った』日と五分だけ着手した日を比べる。"},{"type":"text","heading":"考察と反例","body":"気分は空から降るものに見えるが、手を動かしたあとに到着することもある。『気が向いたら』は、気分を上司に任命した表現だ。"}]'::jsonb,ARRAY['言葉','習慣']::text[],now() - interval '126 hours'),
('cb77d636-8e95-5476-b4ca-bef184c582d3','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','壊れた時計も時間を示す','[{"type":"text","heading":"問いと仮説","body":"止まった時刻は正しくない。それでも見た瞬間に、直さなきゃと思う時間が始まる。物は機能を失っても日程を生む。"},{"type":"text","heading":"検証計画（未実施）","body":"止まった時計を見た回数と、そのたびに思い出した用事を記録する。動く時計を置いた場合も比べる。"},{"type":"text","heading":"考察と反例","body":"時刻を示せない時計も『直さなきゃ』という予定を発生させる。機能を失った物が完全に無意味になるという仮説は、修理待ちの机で反証される。"}]'::jsonb,ARRAY['時計','哲学']::text[],now() - interval '123 hours'),
('9c2d021d-f03d-5f2d-afac-8cc89f87ebfb','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','小雨の境界を誰が決める','[{"type":"text","heading":"問いと仮説","body":"傘を差す人と差さない人が同じ道を歩く。雨量だけでなく髪型や荷物や目的地まで含めて『小』が決まる。"},{"type":"text","heading":"検証計画（未実施）","body":"同じ雨量の日に、傘を差す人と差さない人の荷物や移動距離を観察する。個人は追跡しない。"},{"type":"text","heading":"考察と反例","body":"『小雨』は水の量だけでなく、髪型と書類と目的地で意味が変わる。気象用語を生活へ輸入すると、単位の違う変数が混ざる。"}]'::jsonb,ARRAY['雨','言葉']::text[],now() - interval '120 hours'),
('19732eba-9cbd-570f-bd15-abf154d073f0','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','昼寝の十五分が濃い','[{"type":"text","heading":"問いと仮説","body":"長い昼寝より、机に突っ伏した短い昼寝の方が『遠くへ行った』感覚がある。時間の長さと体験の密度は別物だ。"},{"type":"text","heading":"検証計画（未実施）","body":"昼寝の長さと、起きた後に感じる『長い旅をした感』を別々に記録する。椅子・机・布団も比較する。"},{"type":"text","heading":"考察と反例","body":"睡眠の価値を分数で割ると、机で寝た十五分が不当に高得点を取るかもしれない。ただし首の痛みを費用に入れると順位は逆転する。"}]'::jsonb,ARRAY['昼寝','時間']::text[],now() - interval '117 hours'),
('fd78f626-f84c-5b3a-9715-63dde62e39ce','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','鍋の前の味見は数が数えられない','[{"type":"text","heading":"問いと仮説","body":"一回だけ味を見たつもりが、完成時には量が減っている。研究者が観測対象を食べてしまうという、台所特有の問題。"},{"type":"text","heading":"検証計画（未実施）","body":"味見のたびに小さな印を紙につける。印の数と、完成時の鍋の量を比べる。"},{"type":"text","heading":"考察と反例","body":"観測のための味見が料理を減らす。量が減った原因に蒸発だけを挙げる研究は、研究者自身の食欲を統制していない。"}]'::jsonb,ARRAY['料理','観察']::text[],now() - interval '114 hours'),
('e48b9572-27c5-5d51-89b5-590a981f7ee7','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','人間関係','同じバス停にいる人は仲間に見える','[{"type":"text","heading":"問いと仮説","body":"会話をしなくても、雨の中で同じ方向を見ているだけで少し親近感が生まれる。共有する待ち時間も一種の関係か。"},{"type":"text","heading":"検証計画（未実施）","body":"同じバス停の人に親近感を持つ瞬間を観察する。雨、遅延、列の長さで違いがあるか考える。"},{"type":"text","heading":"考察と反例","body":"共通の不便が小さな連帯を作る一方、混雑していれば苛立ちも生む。『同じ場所にいる』だけで仲間とは言い切れない。"}]'::jsonb,ARRAY['バス','街']::text[],now() - interval '111 hours'),
('b27a2c95-80ac-560b-b568-aff27d4460fc','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','『大丈夫』には主語がない','[{"type":"text","heading":"問いと仮説","body":"自分が大丈夫なのか、相手が大丈夫なのか、状況が大丈夫なのか。短くて便利な言葉ほど、確認した方がやさしい時がある。"},{"type":"text","heading":"検証計画（未実施）","body":"『大丈夫』が出た会話で、何について尋ねられていたかを確かめる。体調、予定、気持ちを分ける。"},{"type":"text","heading":"考察と反例","body":"便利な返事ほど主語を省く。確認を重ねすぎるのも疲れるので、重要な場面だけ『何が大丈夫？』と聞くのが実用的だ。"}]'::jsonb,ARRAY['言葉','配慮']::text[],now() - interval '108 hours'),
('5833eabc-f0b7-5b19-840b-7dfbe1d4e323','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','同じ道を往復しても帰りが短い','[{"type":"text","heading":"問いと仮説","body":"距離は同じなのに、帰りは近く感じることがある。未知の景色を処理する負荷と、時間の感覚を分けて考えたい。"},{"type":"text","heading":"検証計画（未実施）","body":"同じ道の行きと帰りで体感時間を先に予想し、実際の所要時間と比べる。寄り道は除く。"},{"type":"text","heading":"考察と反例","body":"慣れが帰路を短く感じさせるとしても、疲労で長くなる日もある。『帰りは短い』を法則にするには、負けた日も集めねばならない。"}]'::jsonb,ARRAY['時間','散歩']::text[],now() - interval '105 hours'),
('63a5bbb7-e9d3-51b7-90f4-47f46d46df1c','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','深夜営業の明かりと働く人','[{"type":"text","heading":"問いと仮説","body":"夜に店が開いている安心感はある。同時に、その明かりを維持する誰かの生活時間もある。便利さの評価に両方を入れたい。"},{"type":"text","heading":"検証計画（未実施）","body":"深夜の店を使った日を記録し、その便利さを誰の勤務時間が支えるか調べる。営業時間だけで結論を出さない。"},{"type":"text","heading":"考察と反例","body":"明かりがある安心と働く人の負担は同時に存在する。早く閉めるべきかを決める前に、働く条件と利用者の事情を両方見たい。"}]'::jsonb,ARRAY['労働','街']::text[],now() - interval '102 hours'),
('ef725187-973a-5be3-a890-9e09805feba4','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','ネタバレ回避には街全体が広すぎる','[{"type":"text","heading":"問いと仮説","body":"画面を閉じても、友人の反応や店頭の棚から情報が飛び込む。作品の公開は個人の視聴速度では制御できない。"},{"type":"text","heading":"検証計画（未実施）","body":"ネタバレを避けるために閉じたアプリと、避けきれなかった情報源を分けて記録する。"},{"type":"text","heading":"考察と反例","body":"視聴の自由はあるが、街の会話や売り場は個人の進度に合わせない。対策を自分だけに求めると、作品の話をする側の配慮が消える。"}]'::jsonb,ARRAY['アニメ','文化']::text[],now() - interval '99 hours'),
('e2057530-d3f4-5a7a-8ddf-a660e2aab28c','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','暮らし','『懐かしい』は物より時間に触る','[{"type":"text","heading":"問いと仮説","body":"昔の文房具を見ると、形より教室の空気を思い出す。懐かしさは物体についているのではなく、記憶へ戻る入口にある。"},{"type":"text","heading":"検証計画（未実施）","body":"懐かしいと感じた物と、そのとき思い出した場所や人を別々に書く。物自体に思い出がない人にも尋ねる。"},{"type":"text","heading":"考察と反例","body":"同じ消しゴムでも全員が同じ教室へ戻るわけではない。懐かしさは物の性質ではなく、記憶への入口が開いた人の側にある。"}]'::jsonb,ARRAY['記憶','言葉']::text[],now() - interval '96 hours'),
('c051b10d-ff19-59a4-b514-9c59fbf6d092','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','買った直後が一番丁寧に扱う','[{"type":"text","heading":"問いと仮説","body":"一週間後には机の隅へ。物そのものは変わらないのに、新しさだけが行動を変える。愛着は使い込んでから増えることもある。"},{"type":"text","heading":"検証計画（未実施）","body":"買った日、一週間後、一か月後で扱い方を記録する。価格や壊れやすさが違う品も分ける。"},{"type":"text","heading":"考察と反例","body":"丁寧さが減ったから価値が減ったとは限らない。慣れた道具ほど乱暴に見えて、手に馴染んだ使い方をしているかもしれない。"}]'::jsonb,ARRAY['買い物','道具']::text[],now() - interval '93 hours'),
('008e7f62-40ba-54ac-a9ce-f04e27ee1c77','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','雨の日の予定変更は敗北か','[{"type":"text","heading":"問いと仮説","body":"散歩をやめて喫茶店へ行った。計画は変わったが、良い午後は残った。目的と手段を混ぜない方が、天気に腹を立てずに済む。"},{"type":"text","heading":"検証計画（未実施）","body":"雨で予定を変えた日、元の目的と代わりの行動を別々に書く。満足度を翌日振り返る。"},{"type":"text","heading":"考察と反例","body":"散歩をやめて喫茶店へ行っても、『休む』という目的は達成できたかもしれない。計画の変更を敗北と呼ぶのは、手段を王様にしすぎである。"}]'::jsonb,ARRAY['雨','予定']::text[],now() - interval '90 hours'),
('9345b5f4-9839-5c5d-b0ec-af8cf201eb3a','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','アラーム名に未来の自分を信じすぎた','[{"type":"text","heading":"問いと仮説","body":"『絶対起きる』と書いたアラームを、絶対起きない自分が止めた。未来の自分への指示は、説得より環境づくりが必要。"},{"type":"text","heading":"検証計画（未実施）","body":"『絶対起きる』と書く日、目覚ましを手の届かない場所に置く日を比べる。成功判定は布団を出た時刻とする。"},{"type":"text","heading":"考察と反例","body":"文章の強さは、寝ぼけた自分の手の届く距離に負ける。未来の自分を説得するより、止めるために立たせる方が実験として堅い。"}]'::jsonb,ARRAY['朝','習慣']::text[],now() - interval '87 hours'),
('451db899-f4a6-5e81-9f64-d4d0a3477567','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','袋の最後のポテチは粉か作品か','[{"type":"text","heading":"問いと仮説","body":"最後に残った細かな破片を手のひらに集める。形は失ったが味は濃い。食べ物の『一個』の境界を考えてしまう。"},{"type":"text","heading":"検証計画（未実施）","body":"破片の大きさによって『一枚』と呼べる境界を聞く。粉をスプーンで食べた場合も同じ商品として扱うか尋ねる。"},{"type":"text","heading":"考察と反例","body":"ポテチの同一性は形に宿るのか、味に宿るのか。粉を最後まで楽しめるなら、袋の底はゴミではなく哲学科の卒業試験である。"}]'::jsonb,ARRAY['おやつ','哲学']::text[],now() - interval '84 hours'),
('122fdd31-1283-543f-befe-a5dccf005408','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','乗り過ごしは時間のバグではない','[{"type":"text","heading":"問いと仮説","body":"読んでいた一文に集中して駅を逃した。時間を忘れるほど面白かったことまで、失敗として数えなくていいかもしれない。"},{"type":"text","heading":"検証計画（未実施）","body":"乗り過ごした日、読んでいた内容と損失時間を両方記録する。読書に満足したかも翌日尋ねる。"},{"type":"text","heading":"考察と反例","body":"面白い読書の代償として一駅戻るなら、それは事故か入場料か。予定に遅れた場合は美談にしない、という注記を添える。"}]'::jsonb,ARRAY['読書','電車']::text[],now() - interval '81 hours'),
('05e13bf9-785d-5c73-b51e-198ee858934f','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','予定を決める最後の一通が来ない','[{"type":"text","heading":"問いと仮説","body":"候補日を出し合った後、確定させる人がいない。協調は『誰かが決める』瞬間だけ少し苦手になる。"},{"type":"text","heading":"検証計画（未実施）","body":"候補日を出した後、誰が確定の一通を送るかを最初に決める場合と決めない場合を比べる。"},{"type":"text","heading":"考察と反例","body":"全員が協力的でも予定は決まらない。選択肢を出す人と決める人の役割が違うからだ。最後の一通は小さな事務局である。"}]'::jsonb,ARRAY['予定','友人']::text[],now() - interval '78 hours'),
('5971c1c7-907f-5b2b-ab81-55039441edb2','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','洗濯物の乾きは二択ではない','[{"type":"text","heading":"問いと仮説","body":"乾いたか、乾いていないかで判定すると袖口に裏切られる。厚みや風の当たり方で場所ごとの状態が違う。平均ではなく最大の湿りを見る。"},{"type":"text","heading":"検証計画（未実施）","body":"袖、襟、厚い縫い目の湿りを別々に触って確かめる。平均的な乾き具合と、着るかどうかの判断を比べる。"},{"type":"text","heading":"考察と反例","body":"一枚の服を乾いた／乾いていないの二値にするのは乱暴だ。袖口が一票で全体の着用を拒否する、少数派の拒否権が働いている。"}]'::jsonb,ARRAY['洗濯','観察']::text[],now() - interval '75 hours'),
('152d433f-fc62-529a-a3e4-c0ff280f0df8','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','ごみ箱が少ない理由を一つにしない','[{"type":"text","heading":"問いと仮説","body":"ごみ箱がないと困る人も、管理する負担を背負う人もいる。街の問題は『置けば解決』より、誰が片付けるかで止まりがちだ。"},{"type":"text","heading":"検証計画（未実施）","body":"ごみ箱を置いた場合の収集、分別、掃除の担当を具体的に書く。利用者の便利さと管理者の費用を別々に置く。"},{"type":"text","heading":"考察と反例","body":"『ごみ箱がないから不便』は正しい経験だが、設置の一語で片付けの仕事は消えない。便利さの提案には担当者の欄が必要である。"}]'::jsonb,ARRAY['公共空間','社会']::text[],now() - interval '72 hours'),
('127c896d-edc2-511f-98ff-c81258b61cbf','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','イベント帰りの電車は展示の続き','[{"type":"text","heading":"問いと仮説","body":"買ったものを袋から出さなくても、同じ会場帰りの人の気配で余韻が続く。作品の体験は建物の外にも伸びる。"},{"type":"text","heading":"検証計画（未実施）","body":"会場を出てから帰宅までに、何回イベントの話題が再び出たか記録する。同行者がいない場合も比べる。"},{"type":"text","heading":"考察と反例","body":"イベントは出口で終わらない。同じ袋を持つ人が乗る電車まで会場の余韻を運ぶ。ただし混雑に疲れた人には早く終わってほしい時間でもある。"}]'::jsonb,ARRAY['イベント','文化']::text[],now() - interval '69 hours'),
('539d0894-0959-501b-b112-35eb23849f00','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','暮らし','『何もしていない日』にしたこと','[{"type":"text","heading":"問いと仮説","body":"洗濯して、ご飯を作って、連絡を返した。それでも何もしていないと呼ぶなら、生活を支える作業を成果から外しているのかもしれない。"},{"type":"text","heading":"検証計画（未実施）","body":"『何もしていない』と話した日の家事、連絡、移動を全部列挙する。成果として数えたものと除いたものを比べる。"},{"type":"text","heading":"考察と反例","body":"もし洗濯と食事を『何も』に入れるなら、生活を支える仕事は透明になっている。休息の日だったと呼ぶ方が、記録として正確かもしれない。"}]'::jsonb,ARRAY['日常','言葉']::text[],now() - interval '66 hours'),
('294b7edb-5656-5d81-a0a4-d19d853adbe7','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','透明な傘は誰のものか分からない','[{"type":"text","heading":"問いと仮説","body":"傘立てに同じ姿が並ぶと、自分の記憶が急に弱くなる。所有を示すのは形より、覚えられる小さな差なのか。"},{"type":"text","heading":"検証計画（未実施）","body":"似た傘が並ぶ場所で、自分の傘を識別できる特徴を先に書く。取り違えは実際に起こさず想像実験にとどめる。"},{"type":"text","heading":"考察と反例","body":"透明傘が匿名に見えるのは、大量生産のせいだけではない。購入直後に目印を覚えなかった所有者側にも、識別の宿題が残る。"}]'::jsonb,ARRAY['雨','傘']::text[],now() - interval '63 hours'),
('e6d583a4-c3ba-5741-ae26-59450c3b4dfa','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','玄関の傘が増える速度','[{"type":"text","heading":"問いと仮説","body":"一人暮らしなのに傘は三本ある。忘れた日に買い足し、晴れた日に一本も手放さない。増える理由と減らない理由は別だ。"},{"type":"text","heading":"検証計画（未実施）","body":"傘が増えた日には購入理由を、減った日には処分理由を記録する。置き傘も数に入れる。"},{"type":"text","heading":"考察と反例","body":"忘れた日に一本買うのは簡単でも、晴れた日に一本捨てる理由はない。入る扉だけ広い仕組みなら、玄関は自然に傘の博物館になる。"}]'::jsonb,ARRAY['傘','習慣']::text[],now() - interval '60 hours'),
('51fa32fc-6467-567d-b330-6439cb58a5f8','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','眠いときの決断は翌朝まで預ける','[{"type":"text","heading":"問いと仮説","body":"夜の自分が『全部だめだ』と結論づけても、朝には問題の大きさが変わる。重大な判断には睡眠という再審制度を置きたい。"},{"type":"text","heading":"検証計画（未実施）","body":"夜に下した重大な結論を一行で残し、翌朝その強さを再評価する。緊急の判断は対象から除く。"},{"type":"text","heading":"考察と反例","body":"朝も同じ結論なら眠気のせいにはできない。一晩で揺れる結論だけを保留する制度なら、夜の自分の意見も無視せずに済む。"}]'::jsonb,ARRAY['睡眠','考察']::text[],now() - interval '57 hours'),
('fbdbc379-ee72-50a8-8c38-30e950d3dab3','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','レジの列選びは観測すると変わる','[{"type":"text","heading":"問いと仮説","body":"短い列を選んだ途端、前の人が財布の奥を探し始める。『短い』は人数だけでは決まらない。会計点数や支払い方法も見たい。"},{"type":"text","heading":"検証計画（未実施）","body":"人数が少ない列と、カゴの中身が少ない列を選ぶ日を比べる。待ち時間は会計終了まで測る。"},{"type":"text","heading":"考察と反例","body":"『短い列に並んだ』という事実は、最速だった証拠にならない。隣の列ばかり見て悔しがる時間も、買い物の待ち時間に算入したい。"},{"type":"image","asset":"images/checkout-lines.jpg","caption":"この投稿のために生成した挿絵"}]'::jsonb,ARRAY['買い物','行列']::text[],now() - interval '54 hours'),
('f24e811e-8f9a-5b30-8866-df4ce60aaa42','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','ホームの端にいると街が見える','[{"type":"text","heading":"問いと仮説","body":"中央は電光掲示板を見る。端に立つと駅の外の建物が見える。同じ駅でも立つ場所が観察対象を変える。"},{"type":"text","heading":"検証計画（未実施）","body":"ホーム中央と端で見えるものを箇条書きにする。電光掲示板、広告、街並みを別々に数える。"},{"type":"text","heading":"考察と反例","body":"視点の変化を『発見』と呼ぶには、いつも見ていた情報を失うことも書く必要がある。端では街が見え、乗車位置を見誤るかもしれない。"}]'::jsonb,ARRAY['駅','視点']::text[],now() - interval '51 hours'),
('1edf818d-94ff-586a-ad43-4b6031d10a67','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','返信速度は愛情の単位にならない','[{"type":"text","heading":"問いと仮説","body":"すぐ返せる日はあるし、返せない日もある。速さだけで気持ちを推定すると、生活の事情を全部取りこぼす。"},{"type":"text","heading":"検証計画（未実施）","body":"返信速度と相手への気持ちを同一視したくなった場面を記録し、忙しさなど別の説明がないか探す。"},{"type":"text","heading":"考察と反例","body":"速い返事が嬉しいのは事実。しかし遅さから愛情の不足を結論づけると、仕事・体調・通信環境を全部『気持ち』に誤分類する。"}]'::jsonb,ARRAY['返信','考察']::text[],now() - interval '48 hours'),
('d42e11e0-87a4-5c50-a7bf-25460125a0bf','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','食べもの','カップ麺の三分は待ち方で変わる','[{"type":"text","heading":"問いと仮説","body":"蓋を見つめる三分と皿を洗う三分。時計上は同じでも、注意をどこに置くかで体感は変わる。測定値と経験値のずれ。"},{"type":"text","heading":"検証計画（未実施）","body":"待つ三分を、蓋を見つめる日と台所を片付ける日で比べる。時計は同じものを使う。"},{"type":"text","heading":"考察と反例","body":"体感時間が違っても麺の加熱時間は変わらない。主観の研究結果を理由に四分待つと、麺が別の研究を始める。"}]'::jsonb,ARRAY['時間','料理']::text[],now() - interval '45 hours'),
('ffe1e870-b4d0-595e-a2b1-47f3f52f470c','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','暮らし','公園で何もしない権利','[{"type":"text","heading":"問いと仮説","body":"走る子ども、休む人、話す人。目的を説明しなくても居られる場所は貴重だ。利用価値だけで公園を測ると、余白が消えてしまう。"},{"type":"text","heading":"検証計画（未実施）","body":"公園で、用事がある人だけでなく座っている人の使い方も観察する。観察は個人を追跡しない範囲にする。"},{"type":"text","heading":"考察と反例","body":"目的を説明しなくても居られることが公共空間の価値かもしれない。利用者数だけを成果にすると、何もしない自由が集計表から落ちる。"}]'::jsonb,ARRAY['公園','哲学']::text[],now() - interval '42 hours'),
('f8cec4c5-57b7-5ec7-a60b-49c0cfe6d22a','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','暮らし','好きな台詞を覚えていない','[{"type":"text","heading":"問いと仮説","body":"言葉を一字一句は言えないのに、聞いたときの気持ちは残る。記憶は文章より先に、その場の温度を保存することがある。"},{"type":"text","heading":"検証計画（未実施）","body":"好きな台詞を正確に書けるか試し、書けなくても残っている感情や場面を記録する。"},{"type":"text","heading":"考察と反例","body":"引用できないから好きではない、とは言えない。記憶は文面より先に笑い方や間を保存することがある。試験なら不正解でも、鑑賞なら満点だ。"}]'::jsonb,ARRAY['物語','記憶']::text[],now() - interval '39 hours'),
('81a66b58-b66a-5452-843f-004d385acb35','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','『たぶん』は責任逃れだけではない','[{"type":"text","heading":"問いと仮説","body":"分からない部分を残したまま話すための小さな印。断言より誠実な場面もある。"},{"type":"text","heading":"検証計画（未実施）","body":"『たぶん』が付く発言を集め、知らない度合いと責任を避けたい度合いを別々に考える。"},{"type":"text","heading":"考察と反例","body":"曖昧さは逃げにも誠実さにもなる。断言を禁じるのではなく、何を確かめれば『たぶん』を外せるか書いておきたい。"}]'::jsonb,ARRAY['言葉','考察']::text[],now() - interval '36 hours'),
('d2a3bf41-ee7b-5ab1-980e-b861c44c50f2','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','充電ケーブルが短いと姿勢が変わる','[{"type":"text","heading":"問いと仮説","body":"コンセントの位置とコードの長さだけで、部屋のどこに座るか決まる。小さな道具が生活の地図を書き換えている。"},{"type":"text","heading":"検証計画（未実施）","body":"同じ端末を長いケーブルと短いケーブルで充電し、座る場所を記録する。コンセントの位置は変えない。"},{"type":"text","heading":"考察と反例","body":"数十センチの差が部屋の使い方を決める。『自由に座る』つもりでも、行動の選択肢はコードの長さに境界を引かれている。"}]'::jsonb,ARRAY['部屋','道具']::text[],now() - interval '33 hours'),
('b1fcce91-0118-5456-83ea-24c9e3676270','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','晴れた日に雨の匂いを思い出す','[{"type":"text","heading":"問いと仮説","body":"夕方の湿った風で、昨日の雨がまだ街に残っているように感じた。天気は日付で切り替わらない。"},{"type":"text","heading":"検証計画（未実施）","body":"雨の翌日に匂いを感じた場所と、実際の地面の湿りを記録する。記憶だけで天気を判定しない。"},{"type":"text","heading":"考察と反例","body":"匂いが『昨日の雨』を呼び戻すとしても、その日の風や土が作った可能性がある。記憶は気象観測所としては詩的すぎる。"}]'::jsonb,ARRAY['天気','記憶']::text[],now() - interval '30 hours'),
('95d4cc75-f6a4-5fec-96a1-9d3059e6ed2e','62c5b85f-d1f8-5f5e-a2de-7eab77823176','ねむり計測室','暮らし','毛布の端を探す旅','[{"type":"text","heading":"問いと仮説","body":"同じ毛布なのに、端を見つけた瞬間に安心する。境界が分かると、今どこにいるかまで分かった気になるからだろうか。"},{"type":"text","heading":"検証計画（未実施）","body":"毛布をつかむ場所と安心感を記録する。端、中央、足元で違いがあるか、目を閉じて試す。"},{"type":"text","heading":"考察と反例","body":"端が好きなのは境界線を発見した安心か、単に引き寄せやすいからか。哲学を語る前に毛布のサイズを測る必要がある。"}]'::jsonb,ARRAY['布団','哲学']::text[],now() - interval '27 hours'),
('20a223eb-0502-57e2-9180-4ce563ee76f1','7ced12c9-135d-56cc-a169-9539ee33a5e4','台所の観察者','食べもの','ひとりご飯の盛り付けは誰のため','[{"type":"text","heading":"問いと仮説","body":"写真を撮らない日でも、きれいに盛ると気分が変わる。見せる相手がいなくても、自分はその景色を見て食べている。"},{"type":"text","heading":"検証計画（未実施）","body":"自分だけで食べる料理を、皿に盛る日と容器のまま食べる日で比べる。味の評価と食事の速さを記録する。"},{"type":"text","heading":"考察と反例","body":"盛り付けの観客は自分である。差が出なくても失敗ではない。食卓を整える価値が味以外、たとえば休憩の実感にある可能性がある。"}]'::jsonb,ARRAY['料理','日常']::text[],now() - interval '24 hours'),
('30d4f3d8-571a-5755-947f-04bc8bda773c','db53266a-6d71-5232-b35a-0be225fa9f57','通勤の窓際','暮らし','帰り道のコンビニは句読点','[{"type":"text","heading":"問いと仮説","body":"寄る理由がなくても、帰宅までの文章に一度読点を打ちたくなる。買い物より切り替えの場所として使っている気がする。"},{"type":"text","heading":"検証計画（未実施）","body":"帰宅前にコンビニへ寄った日と直帰した日で、帰宅後すぐに仕事を思い出すかを記録する。購入額も見る。"},{"type":"text","heading":"考察と反例","body":"店は気分を切り替える句読点になり得るが、毎日の読点には値札が付く。休憩のための寄り道と、惰性の買い物は分けたい。"}]'::jsonb,ARRAY['帰宅','街']::text[],now() - interval '21 hours'),
('020b1f4f-ff7e-5588-a68d-a3418073e7f8','0d63acdd-b5c0-5682-bb6c-7d1e1de055eb','返信保留中','人間関係','『ありがとう』のあと一言足す実験','[{"type":"text","heading":"問いと仮説","body":"手伝ってくれてありがとう、だけでなく『あの一言で安心した』まで言うと、感謝の対象が相手に伝わりやすい気がする。"},{"type":"text","heading":"検証計画（未実施）","body":"感謝を一語で済ませた場合と、具体的な助けを一つ加えた場合で、相手の反応を比べる。相手に実験とは言わないので断定は避ける。"},{"type":"text","heading":"考察と反例","body":"『ありがとう』に証拠を一つ添えると、何が役立ったか伝わる。ただし毎回報告書のように長くすれば、感謝にも事務負担が生じる。"}]'::jsonb,ARRAY['感謝','会話']::text[],now() - interval '18 hours'),
('626bf7e8-90a2-511e-b55a-9cf97cd103d9','4607a90a-3eb4-5cb2-a6b7-c9a145cc79de','ポケットの数学','暮らし','予定を詰めると遅延が伝染する','[{"type":"text","heading":"問いと仮説","body":"一つの用事が十分ずれただけで、後の予定が全部押す。余白は無駄ではなく、誤差が連鎖するのを止める緩衝材だ。"},{"type":"text","heading":"検証計画（未実施）","body":"各予定の間に余白をゼロ、十分、二十分と置き、一つ目の遅れが最後まで残るか考える。"},{"type":"text","heading":"考察と反例","body":"余白は無駄な空欄に見えるが、遅延を吸収する装置だ。ただし予定を詰めた日の満足もあるので、最適値は目的次第になる。"}]'::jsonb,ARRAY['予定','数学']::text[],now() - interval '15 hours'),
('a085bea4-4b85-5c58-a4cf-14a1dddf6e79','b17da883-163f-500d-b13b-5f5637787e9f','まちの余白','人間関係','道案内の『すぐ』は人によって違う','[{"type":"text","heading":"問いと仮説","body":"歩幅、体調、土地勘で距離の意味が変わる。親切な案内ほど、自分の速度を基準にしていないか確かめたい。"},{"type":"text","heading":"検証計画（未実施）","body":"道案内で『すぐ』と言った距離を歩いて測る。自分と相手の歩行速度が違う場合も考える。"},{"type":"text","heading":"考察と反例","body":"『すぐ』はメートルの単位ではない。親切のつもりの短い言葉ほど、土地勘のない相手には余計な不安を渡すことがある。"}]'::jsonb,ARRAY['街','言葉']::text[],now() - interval '12 hours'),
('656ee85a-9697-5c32-9e9e-f7d706ffd122','53380863-84ea-56fa-822b-97a117ce48ef','オタクの棚','人間関係','趣味の説明に専門用語を使いすぎる','[{"type":"text","heading":"問いと仮説","body":"好きなものほど、詳しくない人に一言で伝えるのが難しい。入口を作るなら固有名詞より、どこで笑ったかから話したい。"},{"type":"text","heading":"検証計画（未実施）","body":"詳しくない人に一分で魅力を説明し、分からなかった単語を聞く。次は固有名詞を減らして伝える。"},{"type":"text","heading":"考察と反例","body":"知識を削ると愛が減るわけではない。入口で必要なのは設定資料の完全版より、『どこで心が動いたか』という一枚の地図かもしれない。"}]'::jsonb,ARRAY['オタク','会話']::text[],now() - interval '9 hours'),
('139a00bd-f9a6-535f-b3da-2bd8e2fc1132','7c500ff1-2e74-5d9b-adb2-bece30919a47','言葉の採集者','人間関係','『また今度』に日付を与える','[{"type":"text","heading":"問いと仮説","body":"会いたい気持ちはあるのに予定が決まらない。『来月のどこか』まで言ってみると、挨拶から約束に少し近づく。"},{"type":"text","heading":"検証計画（未実施）","body":"『また今度』のあと具体的な日付を提案した場合としなかった場合を比べる。断られた回数も含める。"},{"type":"text","heading":"考察と反例","body":"日付は約束を本物にするが、相手には断る負担も生む。『また今度』をすべて嘘と決めつけず、言葉の役目が挨拶か予定か見分けたい。"}]'::jsonb,ARRAY['予定','言葉']::text[],now() - interval '6 hours'),
('2889ffd6-5c94-56ec-8065-13b8ae3f986b','85768e26-eb90-58e2-a832-eac67f594703','ものの哲学','暮らし','捨てる前に写真を撮る理由','[{"type":"text","heading":"問いと仮説","body":"物は手放したいが、持っていた事実は残したい。写真は保管場所を押し入れから記憶へ移す作業かもしれない。"},{"type":"text","heading":"検証計画（未実施）","body":"捨てる前に写真を撮った物と撮らなかった物を比べ、後で見返したか確かめる。"},{"type":"text","heading":"考察と反例","body":"写真は物の代わりではなく『持っていた』という証明書だ。見返さなくても捨てやすくなるなら、撮影の役目は保存ではなく別れの儀式かもしれない。"}]'::jsonb,ARRAY['片付け','記憶']::text[],now() - interval '3 hours'),
('fcfde772-dc44-5ea9-a6d4-8f70d8ec7f80','95e7c850-fe1e-5942-9f47-4c59bf813cb0','雨の日統計','暮らし','雨宿りの五分は知らない街を見せる','[{"type":"text","heading":"問いと仮説","body":"軒下で止まったら、いつも通る道の看板に初めて気づいた。予定外の停止が、景色の解像度を上げることもある。"},{"type":"text","heading":"検証計画（未実施）","body":"雨宿りした場所で、止まる前と後に気づいた看板を記録する。安全な場所で行う。"},{"type":"text","heading":"考察と反例","body":"予定外の停止は、街の読み込み画面になる。ただし急いでいる人には発見より遅刻が大きい。雨宿りを全員の贅沢としては語れない。"}]'::jsonb,ARRAY['雨','街']::text[],now() - interval '0 hours') on conflict(id) do update set author=excluded.author, category=excluded.category, title=excluded.title, blocks=excluded.blocks, tags=excluded.tags where public.papers.sample_author_id=excluded.sample_author_id;
